-- Just shop: перше зчеплення з УкрСкладом (05.10.2026).
--
-- Спершу виконати sync-shop.sql. Потім цей файл — один раз (повтор безпечний).
--
-- Що робить:
--   1. заводить 4 товари, яких на сайті ще не було, з офіційними фото Nike і On;
--   2. вручну чіпляє 4 ID, які за артикулом чи розміром не збігаються:
--      костюм Tech Fleece Grey (в УкрСкладі FB7921-063, насправді світшот CU4505-063),
--      розмір «A» у костюма Dri-Fit Form і Club Set (на сайті S),
--      рюкзак Jam Monogram (на сайті два рядки — «Універсальний» і порожній);
--   3. проганяє таблицю УкрСкладу як повну звірку: кожен із 578 ID зчіплюється
--      зі своїм розміром на сайті, кількість і ціни стають як в УкрСкладі.
-- Закупівельних цін тут немає: сайту вони не потрібні.

-- 1) Нові товари
insert into items (site_id, collection, title, text, price, image_url, extra, sort_order)
select 106, 'products', 'Спортивний костюм чоловічий Tech Woven Black', 'Оригінальний спортивний костюм Nike з Європи. Чоловіча модель. Артикул HM7151-010 + HM7158-010 — за ним модель легко звірити на сайті бренду. Перед відправкою надсилаємо фото бірок, щоб ви переконалися в оригінальності.', '8000', '',
       jsonb_build_object('sku', 'HM7151-010__HM7158-010', 'brand', 'Nike', 'cat', 'kostiumy', 'gender', 'm',
                          'sizes', 'S', 'old', '', 'tag', '', 'weight', '', 'stock', true,
                          'photos', '["https://arikpromax.github.io/justshop/img/n/HM7151-010__HM7158-010-1.webp","https://arikpromax.github.io/justshop/img/n/HM7151-010__HM7158-010-2.webp","https://arikpromax.github.io/justshop/img/n/HM7151-010__HM7158-010-3.webp","https://arikpromax.github.io/justshop/img/n/HM7151-010__HM7158-010-4.webp","https://arikpromax.github.io/justshop/img/n/HM7151-010__HM7158-010-5.webp"]'::jsonb),
       0
 where not exists (select 1 from items where site_id = 106 and collection = 'products'
                     and public.sync_sku(extra->>'sku') = public.sync_sku('HM7151-010__HM7158-010'));

