-- 2) ID, які за артикулом чи розміром не зійдуться самі
-- рюкзак: зайвий рядок без розміру прибираємо, лишається «Універсальний»
delete from stock where site_id = 106 and item_id = 1246 and size = '';
update items set extra = extra || jsonb_build_object('sizes', 'Універсальний') where id = 1246 and site_id = 106;

update stock set ext_id = x.ext
  from (values
    ('362', 1762::bigint, 'XL'),
    ('246', 1246::bigint, 'Універсальний'),
    ('411', (select id from items where site_id = 106 and collection = 'products'
              and public.sync_sku(extra->>'sku') = 'HJ3069-011__HJ3071-010'), 'S'),
    ('357', (select id from items where site_id = 106 and collection = 'products'
              and public.sync_sku(extra->>'sku') = 'HV1165-435'), 'S')
  ) as x(ext, item, size)
 where stock.site_id = 106 and stock.item_id = x.item and stock.size = x.size and stock.ext_id is null
   and not exists (select 1 from stock s2 where s2.site_id = 106 and s2.ext_id = x.ext);

